    "\n    query getUserProfileAttributes($tenantId: String!, $electionEventId: String) {\n        get_user_profile_attributes(tenant_id: $tenantId, election_event_id: $electionEventId) {\n            annotations\n            display_name\n            group\n            multivalued\n            name\n            required\n            validations\n            permissions\n            selector\n        }\n    }\n": typeof types.GetUserProfileAttributesDocument,
