    "\n    query getUsers(\n        $tenant_id: uuid!\n        $election_event_id: uuid\n        $election_id: uuid\n        $email: jsonb\n        $username: jsonb\n        $first_name: jsonb\n        $last_name: jsonb\n        $limit: Int\n        $offset: Int\n        $userIds: [String!]\n        $showVotesInfo: Boolean\n        $attributes: jsonb\n        $enabled: Boolean\n        $email_verified: Boolean\n        $sort: jsonb\n        $has_voted: Boolean\n    ) {\n        get_users(\n            body: {\n                tenant_id: $tenant_id\n                election_event_id: $election_event_id\n                election_id: $election_id\n                email: $email\n                username: $username\n                first_name: $first_name\n                last_name: $last_name\n                limit: $limit\n                offset: $offset\n                user_ids: $userIds\n                show_votes_info: $showVotesInfo\n                attributes: $attributes\n                enabled: $enabled\n                email_verified: $email_verified\n                sort: $sort\n                has_voted: $has_voted\n            }\n        ) {\n            items {\n                id\n                attributes\n                email\n                email_verified\n                enabled\n                first_name\n                groups\n                last_name\n                username\n                area {\n                    id\n                    name\n                }\n                votes_info {\n                    election_id\n                    num_votes\n                    last_voted_at\n                }\n            }\n            total {\n                aggregate {\n                    count\n                }\n            }\n        }\n    }\n": typeof types.GetUsersDocument,
    "\n    mutation ImportApplication(\n        $tenantId: String!\n        $electionEventId: String\n        $electionId: uuid\n        $documentId: String!\n        $sha256: String\n    ) {\n        import_application(\n            tenant_id: $tenantId\n            election_event_id: $electionEventId\n            election_id: $electionId\n            document_id: $documentId\n            sha256: $sha256\n        ) {\n            error_msg\n            document_id\n            task_execution {\n                id\n                name\n                execution_status\n                created_at\n                start_at\n                end_at\n                logs\n                annotations\n                labels\n                executed_by_user\n                tenant_id\n                election_event_id\n                type\n            }\n        }\n    }\n": typeof types.ImportApplicationDocument,
