    "\n    mutation ExportBallotPublication(\n        $tenantId: String!\n        $electionEventId: uuid!\n        $electionId: uuid\n        $ballotPublicationId: String!\n    ) {\n        export_ballot_publication(\n            tenant_id: $tenantId\n            election_event_id: $electionEventId\n            election_id: $electionId\n            ballot_publication_id: $ballotPublicationId\n        ) {\n            document_id\n            task_execution {\n                id\n                name\n                execution_status\n                created_at\n                start_at\n                end_at\n                logs\n                annotations\n                labels\n                executed_by_user\n                tenant_id\n                election_event_id\n                type\n            }\n        }\n    }\n": types.ExportBallotPublicationDocument,
