    "\n    query GetSigningRuleCapacities($electionEventId: uuid!) {\n        initialize_voting: signingRuleCapacity(\n            election_event_id: $electionEventId\n            action: \"initialize-voting\"\n        ) {\n            max\n            posts\n            posts_short\n            posts_short_without_requester\n            roles\n            waiting\n            config_version\n        }\n        open_voting: signingRuleCapacity(\n            election_event_id: $electionEventId\n            action: \"open-voting\"\n        ) {\n            max\n            posts\n            posts_short\n            posts_short_without_requester\n            roles\n            waiting\n            config_version\n        }\n        close_voting: signingRuleCapacity(\n            election_event_id: $electionEventId\n            action: \"close-voting\"\n        ) {\n            max\n            posts\n            posts_short\n            posts_short_without_requester\n            roles\n            waiting\n            config_version\n        }\n        generate_election_returns: signingRuleCapacity(\n            election_event_id: $electionEventId\n            action: \"generate-election-returns\"\n        ) {\n            max\n            posts\n            posts_short\n            posts_short_without_requester\n            roles\n            waiting\n            config_version\n        }\n        generate_reports: signingRuleCapacity(\n            election_event_id: $electionEventId\n            action: \"generate-reports\"\n        ) {\n            max\n            posts\n            posts_short\n            posts_short_without_requester\n            roles\n            waiting\n            config_version\n        }\n        transmit_results: signingRuleCapacity(\n            election_event_id: $electionEventId\n            action: \"transmit-results\"\n        ) {\n            max\n            posts\n            posts_short\n            posts_short_without_requester\n            roles\n            waiting\n            config_version\n        }\n        approve_voter: signingRuleCapacity(\n            election_event_id: $electionEventId\n            action: \"approve-voter\"\n        ) {\n            max\n            posts\n            posts_short\n            posts_short_without_requester\n            roles\n            waiting\n            config_version\n        }\n        approve_configuration: signingRuleCapacity(\n            election_event_id: $electionEventId\n            action: \"approve-configuration\"\n        ) {\n            max\n            posts\n            posts_short\n            posts_short_without_requester\n            roles\n            waiting\n            config_version\n        }\n        key_ceremony: signingRuleCapacity(\n            election_event_id: $electionEventId\n            action: \"key-ceremony\"\n        ) {\n            max\n            posts\n            posts_short\n            posts_short_without_requester\n            roles\n            waiting\n            config_version\n        }\n        tally_key: signingRuleCapacity(election_event_id: $electionEventId, action: \"tally-key\") {\n            max\n            posts\n            posts_short\n            posts_short_without_requester\n            roles\n            waiting\n            config_version\n        }\n    }\n": types.GetSigningRuleCapacitiesDocument,
    "\n    query GetSigningCertificates($electionEventId: uuid!) {\n        checks: sequent_backend_signing_checks(\n            where: {election_event_id: {_eq: $electionEventId}}\n        ) {\n            revocation_check\n            crl_unavailable\n            registration\n            post_binding\n            revision\n            updated_at\n            updated_by_name\n        }\n        issuers: sequent_backend_certificate_authority(\n            where: {election_event_id: {_eq: $electionEventId}, purpose: {_eq: \"staff-signatures\"}}\n            order_by: {created_at: asc}\n        ) {\n            id\n            common_name\n            subject\n            issuer\n            issuer_common_name\n            not_after\n            fingerprint_sha256\n        }\n        certificates: sequent_backend_staff_certificate(\n            where: {election_event_id: {_eq: $electionEventId}}\n            order_by: {registered_at: desc}\n        ) {\n            id\n            user_id\n            username\n            election_id\n            fingerprint_sha256\n            spki_sha256\n            holder_sha256\n            serial\n            subject\n            issuer\n            not_before\n            not_after\n            status\n            registration\n            registered_by\n            registered_at\n            revoked_by\n            revoked_at\n            revoke_reason\n            user_display_name\n            registered_by_name\n            revoked_by_name\n            linked_to\n        }\n        crls: sequent_backend_staff_crl(where: {election_event_id: {_eq: $electionEventId}}) {\n            id\n            issuer_fingerprint\n            url\n            fetched_at\n            status\n        }\n    }\n": types.GetSigningCertificatesDocument,
